function staffInvSchema(d=inventory){if(!d)return;d.settings=d.settings||{};for(const k of ['locations','openingBalances','inventoryMovements','wasteRecords','wasteShiftDeclarations','consumptionRecords','stocktakes','trackedIngredients','salesPeriods'])d[k]=A(d[k]);if(!d.locations.length)d.locations=[{id:'LOC-MAIN',name:'انبار اصلی',type:'main',isActive:true},{id:'LOC-KITCHEN',name:'آشپزخانه',type:'section',isActive:true},{id:'LOC-BAR',name:'بار',type:'section',isActive:true},{id:'LOC-HOOKAH',name:'قلیان',type:'section',isActive:true},{id:'LOC-HALL',name:'سالن / سرویس',type:'section',isActive:true}];d.settings.mainLocationId=d.settings.mainLocationId||d.locations.find(x=>x.type==='main')?.id||'LOC-MAIN';d.settings.defaultSalesLocationId=d.settings.defaultSalesLocationId||'LOC-KITCHEN'}
