function paymentsView(){const key=staffMonthKey(paymentsMonthFilter==='previous'?'previous':'current'),rows=A(hr.payments).filter(x=>x.personnelId===me.id&&S(x.date).startsWith(key)).slice().sort((a,b)=>S(b.date).localeCompare(S(a.date))),total=rows.reduce((a,x)=>a+N(x.amount),0);return `<div class="page-head"><div><h1>دریافتی‌های من</h1><p>فقط ماه جاری و ماه قبل نمایش داده می‌شود.</p></div></div><div class="card"><div class="section-head"><div><h2>${E(key)}</h2><p class="muted">جمع دریافتی: ${F(total)} تومان</p></div><div class="staff-segmented"><button class="btn btn-sm ${paymentsMonthFilter==='current'?'btn-primary':''}" onclick="staffPaymentsMonth('current')">ماه جاری</button><button class="btn btn-sm ${paymentsMonthFilter==='previous'?'btn-primary':''}" onclick="staffPaymentsMonth('previous')">ماه قبل</button></div></div>${staffCompactRows(rows,x=>`<div class="staff-compact-row"><div class="staff-row-main"><b>${E(x.type||'پرداخت')}</b><strong>${F(x.amount)} تومان</strong></div><div class="staff-row-meta"><span>${E(x.date||'—')}</span><span>${E([x.method,x.tracking].filter(Boolean).join(' — ')||'—')}</span><span>${E(x.status||'ثبت‌شده')}</span></div></div>`,'در این ماه دریافتی ثبت نشده است.')}</div>`}
