function reservationsView(){hr.reservations=A(hr.reservations);const rows=hr.reservations.slice().sort((a,b)=>S(b.date).localeCompare(S(a.date))).slice(0,100);return `<div class="page-head"><div><h1>رزرو و بیعانه</h1><p>ثبت توسط صندوقدار</p></div></div><div class="card"><div class="form-grid"><div class="field"><label>تاریخ</label><input id="stResDate" data-jalali="1" value="${today()}"></div><div class="field"><label>ساعت</label><input id="stResTime" type="time"></div><div class="field"><label>نام مشتری</label><input id="stResName"></div><div class="field"><label>تلفن</label><input id="stResPhone" dir="ltr"></div><div class="field"><label>تعداد نفر</label><input id="stResCount" type="number" min="1"></div><div class="field"><label>فضا</label><select id="stResArea"><option value="">انتخاب کنید</option><option>حیاط</option><option>تراس</option><option>سالن</option><option>بدون ترجیح</option></select></div><div class="field"><label>بیعانه (تومان)</label><input id="stResDeposit" type="number" value="0"></div><div class="field"><label>روش بیعانه</label><select id="stResMethod"><option value="">انتخاب کنید</option><option>کارتخوان</option><option>کارت به کارت</option><option>نقدی</option><option>بدون بیعانه</option></select></div><div class="field full"><label>توضیحات</label><textarea id="stResNotes"></textarea></div><div class="full"><button class="btn btn-primary" onclick="staffSaveReservation()">ثبت رزرو</button></div></div></div><div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>تاریخ</th><th>مشتری</th><th>تعداد</th><th>فضا</th><th>بیعانه</th><th>وضعیت</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${E(x.date)} ${E(x.time||'')}</td><td>${E(x.customerName)}<br><small>${E(x.phone||'')}</small></td><td>${F(x.partySize)}</td><td>${E(x.area||'—')}</td><td>${F(x.depositAmount)} تومان</td><td>${E(x.status||'رزرو')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">رزروی ثبت نشده است.</td></tr>'}</tbody></table></div></div>`}
async function staffSaveReservation(){const customerName=S(document.getElementById('stResName')?.value),phone=S(document.getElementById('stResPhone')?.value),date=S(document.getElementById('stResDate')?.value)||today(),partySize=N(document.getElementById('stResCount')?.value);if(!customerName||!phone||partySize<=0)return toastStaff('نام، تلفن و تعداد نفر الزامی است',true);hr=await update('hr',d=>{d.reservations=A(d.reservations);d.reservations.push({id:uid('RES',d.reservations),date,time:S(document.getElementById('stResTime')?.value),customerName,phone,partySize,area:S(document.getElementById('stResArea')?.value),depositAmount:N(document.getElementById('stResDeposit')?.value),depositMethod:S(document.getElementById('stResMethod')?.value),notes:S(document.getElementById('stResNotes')?.value),status:'رزرو',createdByPersonnelId:me.id,createdByName:me.name,createdAt:now()})});toastStaff('رزرو ثبت شد');render()}
assetIncidentView=function(){const all=staffAssetsRows(),countable=all.filter(a=>a.trackingMode==='quantity'),q=assetIncidentSearch.toLowerCase(),visible=countable.filter(a=>!q||`${a.itemId||''} ${a.name}`.toLowerCase().includes(q)).slice(0,10),selected=countable.find(a=>a.id===assetIncidentSelectedId),rows=A(assets?.assetIncidents).filter(x=>x.reportedByPersonnelId===me.id).slice().sort((a,b)=>S(b.createdAt).localeCompare(S(a.createdAt)));return `<div class="page-head"><div><h1>ثبت شکستگی، آسیب یا مفقودی</h1><p>برای دارایی‌های شمارشی از جست‌وجوی زیر استفاده کنید؛ فهرست انتخاب در همان صفحه و محدود نمایش داده می‌شود.</p></div></div><div class="card"><div class="form-grid"><div class="field full"><label>جست‌وجوی دارایی شمارشی</label><input value="${E(assetIncidentSearch)}" oninput="staffAssetSearch(this.value)" placeholder="نام یا کد"></div><div class="field full"><label>انتخاب دارایی شمارشی</label><input type="hidden" id="stAssetIncAsset" value="${E(assetIncidentSelectedId)}"><div class="staff-asset-picker">${visible.map(a=>`<button type="button" class="staff-asset-option ${a.id===assetIncidentSelectedId?'selected':''}" onclick="staffAssetChoose('${E(a.id)}')"><b>${E(a.name)}</b><small>${E(a.itemId||'')}</small></button>`).join('')||'<div class="staff-compact-empty">موردی پیدا نشد.</div>'}</div>${selected?`<div class="success-box">انتخاب‌شده: <b>${E(selected.name)}</b></div>`:''}</div><div class="field"><label>سایر دارایی / شماره اموال</label><input id="stAssetIncCustom" placeholder="اگر در فهرست نیست اینجا بنویسید"></div><div class="field"><label>نوع اتفاق</label><select id="stAssetIncType"><option value="">انتخاب کنید</option><option>شکستگی</option><option>مفقودی</option><option>آسیب/خرابی</option><option>خروج از رده</option></select></div><div class="field"><label>تعداد (عدد)</label><input id="stAssetIncQty" type="number" min="1" value="1"></div><div class="field"><label>تاریخ</label><input id="stAssetIncDate" data-jalali="1" value="${today()}"></div><div class="field full"><label>شرح اتفاق</label><textarea id="stAssetIncDesc"></textarea></div><div class="full"><button class="btn btn-primary" onclick="staffSaveAssetIncident()">ثبت گزارش</button></div></div></div><div class="card"><div class="section-head"><h2>گزارش‌های ثبت‌شده من</h2></div>${staffCompactRows(rows,r=>`<div class="staff-compact-row"><div class="staff-row-main"><b>${E(r.assetName||staffAssetsRows().find(a=>a.id===r.assetId)?.name||'—')}</b><span class="badge">${E(r.type)}</span></div><div class="staff-row-meta"><span>${E(r.date)}</span><span>تعداد: ${F(r.quantity||1)}</span><span>${E(r.status||'جدید')}</span><span>${E(r.description||'—')}</span></div></div>`,'گزارشی ثبت نشده است.')}</div>`}
